def trim_history(messages, budget):
    if not isinstance(messages, (list, tuple)):
        raise ValueError("messages must be a sequence")
    if not isinstance(budget, int) or isinstance(budget, bool):
        raise ValueError("budget must be an integer")
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for m in messages:
        cost = m.get("cost")
        if not isinstance(cost, int) or isinstance(cost, bool):
            raise ValueError("every message cost must be an integer")
        if cost < 0:
            raise ValueError("every message cost must be nonnegative")

    n = len(messages)
    total = sum(m["cost"] for m in messages)
    start = 0
    while start < n and total - messages[start]["cost"] <= budget:
        total -= messages[start]["cost"]
        start += 1
    return list(messages[start:])

