def merge_tool_results(calls, results):
    last_by_id = {}
    for result in results:
        last_by_id[result['id']] = result

    seen_call_ids = set()
    output = []
    for call in calls:
        call_id = call['id']
        if call_id in seen_call_ids:
            raise ValueError("duplicate call id: %r" % (call_id,))
        seen_call_ids.add(call_id)

        if call_id in last_by_id:
            result = last_by_id[call_id]
            content = result.get('content', '')
            output.append({'id': call_id, 'status': 'done', 'content': content})
        else:
            output.append({'id': call_id, 'status': 'pending'})

    return output

