def summarize_usage(events):
    totals = {'input': 0, 'output': 0}
    maxes = {}
    for event in events:
        request_id = event['request_id']
        counts = {}
        for key in ('input', 'output'):
            value = event.get(key, 0)
            if value < 0:
                raise ValueError('negative token count: %r' % (key,))
            counts[key] = value
        if request_id in maxes:
            maxes[request_id]['input'] = max(maxes[request_id]['input'], counts['input'])
            maxes[request_id]['output'] = max(maxes[request_id]['output'], counts['output'])
        else:
            maxes[request_id] = counts
    for counts in maxes.values():
        totals['input'] += counts['input']
        totals['output'] += counts['output']
    return totals

